(function() {
const BASE_URL = document.querySelector('meta[name="base-url"]')?.content
|| document.querySelector('meta[base-url]')?.content
|| '';
function renderHtmlAdInIframe(adDiv, htmlContent) {
adDiv.innerHTML = '';
const iframe = document.createElement('iframe');
iframe.style.cssText = 'width:100%;height:100%;border:none;display:block;overflow:hidden;background:transparent;';
const safeDirectRender = (div, content) => {
div.innerHTML = '';
const parser = new DOMParser();
const doc = parser.parseFromString(content, 'text/html');
const nodes = Array.from(doc.body.childNodes);
nodes.forEach(node => {
if (node.tagName === 'SCRIPT') {
const newScript = document.createElement('script');
Array.from(node.attributes).forEach(attr => newScript.setAttribute(attr.name, attr.value));
newScript.textContent = node.textContent;
div.appendChild(newScript);
} else {
div.appendChild(node);
}
});
const headScripts = Array.from(doc.head.querySelectorAll('script'));
headScripts.forEach(node => {
const newScript = document.createElement('script');
Array.from(node.attributes).forEach(attr => newScript.setAttribute(attr.name, attr.value));
newScript.textContent = node.textContent;
div.appendChild(newScript);
});
};
if ('srcdoc' in iframe) {
iframe.srcdoc = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
html, body { margin: 0; padding: 0; background: transparent; overflow: hidden; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; }
</style>
</head>
<body>
${htmlContent}
</body>
</html>
`;
adDiv.appendChild(iframe);
} else {
adDiv.appendChild(iframe);
try {
const doc = iframe.contentDocument || iframe.contentWindow.document;
doc.open();
doc.write(`
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
html, body { margin: 0; padding: 0; background: transparent; overflow: hidden; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; }
</style>
</head>
<body>
${htmlContent}
</body>
</html>
`);
doc.close();
} catch (e) {
console.error('Failed to write to iframe, falling back to direct render:', e);
safeDirectRender(adDiv, htmlContent);
}
}
}
function detectDeviceType() {
if (window.innerWidth <= 900) {
return "mobile";
}
return "desktop";
}
const device = detectDeviceType();
function setupAdReload(container, reloadSeconds) {
if (container.dataset.reloadIntervalId) {
clearInterval(parseInt(container.dataset.reloadIntervalId));
delete container.dataset.reloadIntervalId;
}
if (!reloadSeconds || reloadSeconds <= 0) {
return;
}
const intervalId = setInterval(() => {
if (!document.body.contains(container)) {
clearInterval(intervalId);
return;
}
loadAd(container);
}, reloadSeconds * 1000);
container.dataset.reloadIntervalId = intervalId;
}
async function loadAd(container) {
const placement = container.dataset.placement;
const position = container.dataset.position || 1;
const videoId = container.dataset.videoId || window.FH_WATCH?.videoId || '';
try {
const url = `${BASE_URL}/api/ads.php?action=get_ad&placement=${placement}&position=${position}&device=${device}&video_id=${videoId}`;
const response = await fetch(url);
const data = await response.json();
let reloadSeconds = parseInt(container.dataset.reloadInterval) || 0;
if (data.success && data.ad) {
const ad = data.ad;
if (ad.reload_interval !== undefined) {
reloadSeconds = parseInt(ad.reload_interval) || 0;
container.dataset.reloadInterval = reloadSeconds;
}
container.classList.add('loaded');
container.style.display = '';
container.classList.remove('ad-mobile-only', 'ad-desktop-only', 'ad-has-dimensions');
const placementDevice = container.dataset.deviceTarget || 'all';
if (ad.device_target === 'mobile' || placementDevice === 'mobile') {
container.classList.add('ad-mobile-only');
} else if (ad.device_target === 'desktop' || placementDevice === 'desktop') {
container.classList.add('ad-desktop-only');
}
if (ad.ad_width || ad.ad_height) {
container.classList.add('ad-has-dimensions');
}
if (placement === 'home_mobile_top') {
} else {
container.style.width = '';
container.style.maxWidth = '';
container.style.height = '';
container.style.padding = '';
container.style.display = '';
container.style.flexDirection = '';
container.style.justifyContent = '';
if (ad.ad_width) {
container.style.width = '100%';
container.style.maxWidth = ad.ad_width + 'px';
}
if (ad.ad_height) {
container.style.height = ad.ad_height + 'px';
container.style.padding = '0';
container.style.display = 'flex';
container.style.flexDirection = 'column';
container.style.justifyContent = 'center';
}
}
let sizeStyle = '';
if (placement === 'home_mobile_top') {
sizeStyle += 'width: 100% !important; ';
} else if (ad.ad_width) {
sizeStyle += `width: 100%; max-width: ${ad.ad_width}px; `;
}
if (ad.ad_height) sizeStyle += `height: 100%; max-height: ${ad.ad_height}px; `;
const wrapper = document.createElement('div');
wrapper.style.cssText = `margin: 0 auto; display: block; max-width: 100%; ${sizeStyle}`;
wrapper.className = 'ad-creative-wrapper';
if (ad.content_type === 'image' && ad.image_url) {
const imgLink = document.createElement('a');
imgLink.href = ad.target_url || '#';
imgLink.target = '_blank';
imgLink.rel = 'noopener';
imgLink.style.cssText = 'display: block; width: 100%; height: 100%;';
imgLink.className = 'ad-click-link';
imgLink.dataset.adId = ad.id;
imgLink.dataset.videoId = videoId;
const img = document.createElement('img');
img.src = ad.image_url;
img.alt = ad.title;
img.style.cssText = `width: 100%; ${ad.ad_height ? 'height: 100%; object-fit: contain;' : 'height: auto;'} display: block; border-radius: 4px;`;
imgLink.appendChild(img);
wrapper.appendChild(imgLink);
} else if (ad.content_type === 'html') {
const adDiv = document.createElement('div');
adDiv.className = 'ad-html-content';
adDiv.style.cssText = `width: 100%; ${ad.ad_height ? 'height: 100%;' : ''} display: block; margin: 0 auto; overflow: hidden;`;
wrapper.appendChild(adDiv);
} else {
const txtLink = document.createElement('a');
txtLink.href = ad.target_url || '#';
txtLink.target = '_blank';
txtLink.rel = 'noopener';
txtLink.className = 'ad-click-link';
txtLink.dataset.adId = ad.id;
txtLink.dataset.videoId = videoId;
txtLink.style.cssText = 'font-weight: bold; color: var(--accent); text-decoration: underline;';
txtLink.textContent = ad.content || ad.title;
wrapper.appendChild(txtLink);
}
const existingWrapper = container.querySelector('.ad-creative-wrapper');
if (existingWrapper) {
existingWrapper.replaceWith(wrapper);
} else {
container.innerHTML = '';
container.appendChild(wrapper);
}
if (ad.content_type === 'html') {
const adDiv = wrapper.querySelector('.ad-html-content');
if (adDiv) {
renderHtmlAdInIframe(adDiv, ad.content);
}
}
trackImpression(ad.id, videoId, placement);
container.dataset.processed = "true";
setupAdReload(container, reloadSeconds);
} else {
container.style.display = 'none';
setupAdReload(container, reloadSeconds);
}
} catch (e) {
console.error('Failed to load ad:', e);
container.style.display = 'none';
const reloadSeconds = parseInt(container.dataset.reloadInterval) || 0;
setupAdReload(container, reloadSeconds);
}
}
let detectionsPromise = null;
let adBlockDetected = false;
let vpnDetected = false;
function showMonetizationWarning(message) {
const banner = document.getElementById('monetization-warning-banner');
if (banner) {
banner.textContent = message;
banner.style.display = 'block';
}
}
async function checkAdBlock() {
return new Promise((resolve) => {
const testAd = document.createElement('div');
testAd.innerHTML = '&nbsp;';
testAd.className = 'adsbox adframe banner-ad doubleclick-ad';
testAd.style.cssText = 'position:absolute; top:-1000px; left:-1000px; width:1px; height:1px;';
document.body.appendChild(testAd);
window.setTimeout(async () => {
const isBlocked = (testAd.offsetHeight === 0 || testAd.style.display === 'none' || window.getComputedStyle(testAd).display === 'none');
testAd.remove();
if (isBlocked) {
resolve(true);
} else {
try {
await fetch(`${BASE_URL}/api/ads.php?action=get_ad&placement=test_ad_block`, { method: 'HEAD', cache: 'no-store' });
resolve(false);
} catch (e) {
resolve(true);
}
}
}, 100);
});
}
async function checkVpn() {
try {
const res = await fetch('https://ipapi.co/json/');
const data = await res.json();
const org = (data.org || '').toLowerCase();
const asn = (data.asn || '').toLowerCase();
const vpnKeywords = [
'vpn', 'proxy', 'hosting', 'server', 'cloud', 'digitalocean', 'linode', 'hetzner', 'ovh', 'amazon', 'google',
'microsoft', 'mullvad', 'nord', 'expressvpn', 'tor', 'exit', 'datacenter', 'choopa', 'leaseweb', 'vultr', 'm247'
];
for (let keyword of vpnKeywords) {
if (org.includes(keyword) || asn.includes(keyword)) {
return true;
}
}
} catch (e) {
}
return false;
}
async function runDetections() {
adBlockDetected = await checkAdBlock();
if (adBlockDetected) {
showMonetizationWarning("Ad Blocker detected. Earnings are disabled while Ad Blocker is active. Please disable it to continue earning.");
return;
}
vpnDetected = await checkVpn();
if (vpnDetected) {
showMonetizationWarning("VPN detected. Earnings are disabled while VPN is active. Please disable VPN to continue earning.");
try {
await fetch(`${BASE_URL}/api/ads.php?action=set_vpn_session`, { method: 'POST' });
} catch(e) {}
}
}
async function trackImpression(adId, videoId, placement) {
if (detectionsPromise) {
try {
await detectionsPromise;
} catch(e) {}
}
if (adBlockDetected || vpnDetected) {
console.warn('Impression tracking skipped: AdBlock or VPN active.');
return;
}
const vid = videoId || '';
const plc = placement || '';
try {
await fetch(`${BASE_URL}/api/ads.php?action=track_impression&id=${adId}&video_id=${vid}&placement=${encodeURIComponent(plc)}`, { method: 'POST' });
} catch(e) {}
}
async function trackClick(adId, videoId, placement) {
if (detectionsPromise) {
try {
await detectionsPromise;
} catch(e) {}
}
if (adBlockDetected || vpnDetected) {
console.warn('Click tracking skipped: AdBlock or VPN active.');
return;
}
const vid = videoId || '';
const plc = placement || '';
try {
await fetch(`${BASE_URL}/api/ads.php?action=track_click&id=${adId}&video_id=${vid}&placement=${encodeURIComponent(plc)}`, { method: 'POST' });
} catch(e) {}
}
document.addEventListener('click', function(ev) {
const link = ev.target.closest('.ad-click-link');
if (link && link.dataset.adId) {
const adId = link.dataset.adId;
const videoId = link.dataset.videoId || window.FH_WATCH?.videoId || '';
const container = link.closest('.ad-sponsored-container');
const placement = container ? (container.dataset.placement || '') : '';
trackClick(adId, videoId, placement);
}
});
function processAdContainer(container) {
if (container.dataset.processed === "true") {
return;
}
const template = container.querySelector('.ad-html-template');
const htmlContentEl = container.querySelector('.ad-html-content');
if (template && htmlContentEl) {
container.dataset.processed = "true";
const content = template.innerHTML;
renderHtmlAdInIframe(htmlContentEl, content);
const reloadSeconds = parseInt(container.dataset.reloadInterval) || 0;
if (reloadSeconds > 0) {
setupAdReload(container, reloadSeconds);
}
const adId = container.dataset.adId;
const videoId = container.dataset.videoId || window.FH_WATCH?.videoId || '';
const placement = container.dataset.placement || '';
if (adId) {
trackImpression(adId, videoId, placement);
}
} else if (container.querySelector('.ad-click-link, .ad-html-content')) {
container.dataset.processed = "true";
const reloadSeconds = parseInt(container.dataset.reloadInterval) || 0;
if (reloadSeconds > 0) {
setupAdReload(container, reloadSeconds);
}
const adId = container.dataset.adId;
const videoId = container.dataset.videoId || window.FH_WATCH?.videoId || '';
const placement = container.dataset.placement || '';
if (adId) {
trackImpression(adId, videoId, placement);
}
} else {
loadAd(container);
}
}
async function initAds() {
detectionsPromise = runDetections().catch(err => {
console.error('runDetections failed:', err);
});
const containers = document.querySelectorAll('.ad-sponsored-container');
containers.forEach(container => {
if (container.dataset.lazy === "true") {
return;
}
processAdContainer(container);
});
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', initAds);
} else {
initAds();
}
window.initAds = initAds;
window.loadLazyAd = function(container) {
if (container && container.classList.contains('ad-sponsored-container')) {
delete container.dataset.lazy;
processAdContainer(container);
}
};
window.reloadAd = function(container) {
if (container && container.classList.contains('ad-sponsored-container')) {
delete container.dataset.lazy;
loadAd(container);
}
};
})();